SELECT ano,   SUM(total_deaths) AS mortes,   SUM(total_dafw_cases + total_djtr_cases + total_other_cases) AS casos_registraveis,   SUM(total_hours_worked) AS horas_trabalhadas,   ROUND(SUM(total_dafw_cases + total_djtr_cases + total_other_cases) * 200000.0 / NULLIF(SUM(total_hours_worked),0), 2) AS trir,   ROUND(SUM(total_dafw_cases + total_djtr_cases) * 200000.0 / NULLIF(SUM(total_hours_worked),0), 2) AS dart FROM {{ source('bronze', 'osha_ita') }} GROUP BY ano
